    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a)  {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x)  {
    printf("%d ", x);
}
void emitstr(int* a, int n)  {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void)  {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int ans = 0, h = 0, i = 0, left = 0, n = 0, top = 0, x = 0;
    n = read();
    for (i = 0; i < n; i += 1)  {
        a[i] = read();
    }
    top = 0;
    ans = 0;
    for (i = 0; i < (n + 1); i += 1)  {
        h = 0;
        if (i < n)  {
            h = a[i];
        }
        /* 当前柱更矮时弹出所有更高候选，宽度不包含 left 与 i 两侧边界。 */
        while ((top > 0) && (a[b[(top - 1)]] > h))  {
            top = (top - 1);
            x = a[b[top]];
            left = (-1);
            if (top > 0)  {
                left = b[(top - 1)];
            }
            ans = mx(ans, (x * ((i - left) - 1)));
        }
        b[top] = i;
        top = (top + 1);
    }
    /* ans 保留面积最大值，末尾虚拟高度 0 负责结算尚未出栈的正高度柱。 */
    emit(ans);
    return 0;
}

